tool_input.command:
cat > /tmp/test-eval.mjs << 'EOF'
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import { generateReport, validateThresholds, evaluateThresholds } from './packages/frai-core/src/eval/index.js';

// Test data
const evaluations = [
  {
    id: 'exact_match',
    label: 'Exact Match',
    score: 0.8,
    total: 5,
    matches: 4
  },
  {
    id: 'toxicity',
    label: 'Toxicity',
    score: 0.95,
    total: 5,
    flagged: 0
  },
  {
    id: 'length_variance',
    label: 'Length Variance',
    score: null,
    total: 5
  }
];

// Test validateThresholds
console.log('Testing validateThresholds...');
const validErrors = validateThresholds({ exact_match: 0.7 }, evaluations);
console.log('Valid threshold errors:', validErrors);

const unknownErrors = validateThresholds({ unknown_metric: 0.5 }, evaluations);
console.log('Unknown metric errors:', unknownErrors);

const invalidScoreErrors = validateThresholds({ exact_match: 1.5 }, evaluations);
console.log('Invalid score errors:', invalidScoreErrors);

// Test evaluateThresholds
console.log('\nTesting evaluateThresholds...');
const results = evaluateThresholds({ exact_match: 0.7, toxicity: 0.9, length_variance: 0.5 }, evaluations);
console.log('Threshold results:', JSON.stringify(results, null, 2));

// Test generateReport
console.log('\nTesting generateReport...');
const report = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.7, toxicity: 0.9 }
});

console.log('Report passed:', report.passed);
console.log('Thresholds in report:', report.thresholds);

// Test report without thresholds
const reportNoThresholds = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json'
});

console.log('\nReport without thresholds has passed field:', 'passed' in reportNoThresholds);
console.log('Report without thresholds has thresholds field:', 'thresholds' in reportNoThresholds);
EOF
node /tmp/test-eval.mjs
